import { teamMembers } from "@/data/home";
import { PhotoSlot } from "@/components/ui/PhotoSlot";
import { SectionHeading } from "@/components/ui/SectionHeading";
export function PeopleShowcase() { const lead = teamMembers[0]; return <section id="people" className="people section-dark"><SectionHeading number="03" title="THE PEOPLE" description="The minds and hearts behind the movement." /><div className="people-stage"><div className="people-copy"><p className="section-number">01</p><h3>{lead.name}</h3><p className="eyebrow">{lead.role}</p><p>Building communities, creating opportunities.</p><span className="asset-note">Profile bio and social links to be verified.</span></div><PhotoSlot className="portrait-slot" label={`${lead.name} portrait`} /></div><ol className="member-strip">{teamMembers.map((member, index) => <li key={member.name}><span>{String(index + 1).padStart(2, "0")}</span>{member.name}</li>)}</ol></section>; }
